// Shared helpers and widgets — generated by `mcn build --target flutter`.
import 'package:flutter/material.dart';

// ── MCN value helpers (MCN data arrives as JSON: maps, lists, strings, numbers) ──

/// MCN truthiness: null, false, 0, "", [] and {} are false.
bool truthy(dynamic v) {
  if (v == null || v == false) return false;
  if (v is num) return v != 0;
  if (v is String) return v.isNotEmpty;
  if (v is Iterable) return v.isNotEmpty;
  if (v is Map) return v.isNotEmpty;
  return true;
}

/// `a.b` on JSON data (and `.length` on lists / strings).
dynamic mcnGet(dynamic obj, String key) {
  if (obj is Map) return obj[key];
  if (key == 'length') {
    if (obj is List) return obj.length;
    if (obj is String) return obj.length;
  }
  return null;
}

/// `a[i]` with negative indexes and null when out of range (MCN semantics).
dynamic mcnIndex(dynamic obj, dynamic index) {
  if (obj is List && index is int) {
    final i = index < 0 ? obj.length + index : index;
    return (i >= 0 && i < obj.length) ? obj[i] : null;
  }
  if (obj is String && index is int) {
    final i = index < 0 ? obj.length + index : index;
    return (i >= 0 && i < obj.length) ? obj[i] : null;
  }
  if (obj is Map) return obj[index] ?? obj[index.toString()];
  return null;
}

/// `+` with MCN semantics: string if either side is a string.
dynamic mcnAdd(dynamic a, dynamic b) {
  if (a is String || b is String) return '${mcnStr(a)}${mcnStr(b)}';
  if (a is num && b is num) return a + b;
  if (a is List && b is List) return [...a, ...b];
  return '${mcnStr(a)}${mcnStr(b)}';
}

/// Display text for any value ("" for null, 1500.0 → "1500").
String mcnStr(dynamic v) {
  if (v == null) return '';
  if (v is double && v == v.roundToDouble() && v.abs() < 1e15) return v.toInt().toString();
  return v.toString();
}

/// Items to loop over (a list, or nothing).
List<dynamic> mcnList(dynamic v) => v is List ? v : const [];

/// 1234567.5 → "12,34,567.5" (Indian grouping) or "1,234,567.5".
String formatNumber(dynamic v, {bool indian = false}) {
  if (v == null || v == '') return '';
  final n = v is num ? v : num.tryParse(v.toString());
  if (n == null) return v.toString();
  final negative = n < 0;
  final parts = mcnStr(n.abs()).split('.');
  var whole = parts[0];
  final out = StringBuffer();
  if (indian && whole.length > 3) {
    final tail = whole.substring(whole.length - 3);
    var head = whole.substring(0, whole.length - 3);
    final groups = <String>[];
    while (head.length > 2) {
      groups.insert(0, head.substring(head.length - 2));
      head = head.substring(0, head.length - 2);
    }
    if (head.isNotEmpty) groups.insert(0, head);
    whole = '${groups.join(',')},$tail';
  } else {
    final buf = StringBuffer();
    for (var i = 0; i < whole.length; i++) {
      if (i > 0 && (whole.length - i) % 3 == 0) buf.write(',');
      buf.write(whole[i]);
    }
    whole = buf.toString();
  }
  out.write(negative ? '-' : '');
  out.write(whole);
  if (parts.length > 1) out.write('.${parts[1]}');
  return out.toString();
}

String humanize(String s) {
  final text = s.replaceAll('_', ' ');
  return text.isEmpty ? text : text[0].toUpperCase() + text.substring(1);
}

/// Colour by meaning first (won → green, lost → red …), then by position.
Color badgeColor(String value, [int index = 0]) {
  const green = Color(0xFF15803D), red = Color(0xFFBE123C), blue = Color(0xFF1D4ED8);
  const amber = Color(0xFFB45309);
  const semantic = <String, Color>{
    'won': green, 'done': green, 'completed': green, 'approved': green, 'paid': green,
    'active': green, 'yes': green, 'low': green, 'resolved': green,
    'lost': red, 'rejected': red, 'failed': red, 'cancelled': red, 'blocked': red,
    'overdue': red, 'high': red, 'urgent': red,
    'new': blue, 'open': blue, 'todo': blue, 'draft': blue,
    'pending': amber, 'contacted': amber, 'in_progress': amber, 'medium': amber,
    'qualified': amber, 'review': amber,
  };
  const palette = [Color(0xFF1D4ED8), Color(0xFF6D28D9), Color(0xFF0E7490),
                   Color(0xFFB45309), Color(0xFFA21CAF), Color(0xFF475569)];
  return semantic[value.toLowerCase()] ?? palette[index % palette.length];
}

// ── Widgets ──────────────────────────────────────────────────────────────────

class McnBadge extends StatelessWidget {
  const McnBadge(this.text, {super.key, this.color});

  final String text;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final c = color ?? badgeColor(text);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
      decoration: BoxDecoration(
        color: c.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(6),
      ),
      child: Text(humanize(text),
          style: TextStyle(color: c, fontSize: 12, fontWeight: FontWeight.w600)),
    );
  }
}

class StatCard extends StatelessWidget {
  const StatCard({super.key, required this.label, required this.value, this.unit = '',
      this.icon = Icons.insights_outlined, this.color});

  final String label;
  final String value;
  final String unit;
  final IconData icon;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final c = color ?? theme.colorScheme.primary;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(children: [
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(label, style: theme.textTheme.bodySmall),
              const SizedBox(height: 4),
              Text('$value${unit.isEmpty ? '' : ' $unit'}',
                  style: theme.textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)),
            ]),
          ),
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
                color: c.withValues(alpha: 0.12), borderRadius: BorderRadius.circular(10)),
            child: Icon(icon, color: c),
          ),
        ]),
      ),
    );
  }
}

class McnAlert extends StatelessWidget {
  const McnAlert(this.text, {super.key, this.destructive = false});

  final String text;
  final bool destructive;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final c = destructive ? scheme.error : scheme.primary;
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        border: Border.all(color: c.withValues(alpha: 0.4)),
        borderRadius: BorderRadius.circular(8),
        color: c.withValues(alpha: 0.06),
      ),
      child: Text(text, style: TextStyle(color: destructive ? scheme.error : null)),
    );
  }
}

/// `div grid_cols=N`: N columns on wide screens, fewer on phones.
class ResponsiveGrid extends StatelessWidget {
  const ResponsiveGrid({super.key, required this.columns, required this.children});

  final int columns;
  final List<Widget> children;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(builder: (context, box) {
      final cols = box.maxWidth < 420 ? 1 : (box.maxWidth < 720 ? (columns < 2 ? columns : 2) : columns);
      const gap = 12.0;
      final width = (box.maxWidth - gap * (cols - 1)) / cols;
      return Wrap(
        spacing: gap,
        runSpacing: gap,
        children: [for (final c in children) SizedBox(width: width, child: c)],
      );
    });
  }
}

/// Simple table for `table` elements: header labels + rows of cell widgets.
class McnTable extends StatelessWidget {
  const McnTable({super.key, required this.headers, required this.rows});

  final List<String> headers;
  final List<List<Widget>> rows;

  @override
  Widget build(BuildContext context) {
    final head = Theme.of(context).textTheme.labelMedium;
    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        headingRowHeight: 40,
        columns: [for (final h in headers) DataColumn(label: Text(h, style: head))],
        rows: [
          for (final r in rows)
            DataRow(cells: [
              for (var i = 0; i < headers.length; i++)
                DataCell(i < r.length ? r[i] : const SizedBox.shrink()),
            ]),
        ],
      ),
    );
  }
}

/// Show a short message at the bottom of the screen (MCN `toast`).
void showToast(BuildContext context, dynamic message) {
  ScaffoldMessenger.maybeOf(context)
      ?.showSnackBar(SnackBar(content: Text(mcnStr(message))));
}

/// Ask a yes/no question (MCN `confirm`).
Future<bool> mcnConfirm(BuildContext context, dynamic message) async {
  final ok = await showDialog<bool>(
    context: context,
    builder: (c) => AlertDialog(
      content: Text(mcnStr(message)),
      actions: [
        TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(c, true), child: const Text('OK')),
      ],
    ),
  );
  return ok ?? false;
}
